-- PostgreSQL temporário e schema Storage simulado. Nunca executar no operacional.
begin;
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002'),('00000000-0000-4000-8000-000000000003'),('00000000-0000-4000-8000-000000000004');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
select public.create_business('Trabalhos A','posts-a','autonomo','mundo-novo-ms') as a \gset
select public.portfolio_command('prepare',:'a','00000000-0000-4000-8000-000000000101');
select public.portfolio_command('prepare',:'a','00000000-0000-4000-8000-000000000102');
insert into storage.objects(bucket_id,name,metadata) select 'business-portfolio',storage_path,'{"size":100,"mimetype":"image/webp"}'::jsonb from public.portfolio_items where business_id=:'a';
select public.portfolio_command('finalize',:'a','00000000-0000-4000-8000-000000000101');
select public.portfolio_command('finalize',:'a','00000000-0000-4000-8000-000000000102');
select public.work_post_command('save',:'a','00000000-0000-4000-8000-000000000201','Trabalho técnico','Descrição',array['00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000102']::uuid[]);
select test.assert_true((select status='draft' from public.work_posts),'publicações: criação começa draft');
select public.work_post_command('save',:'a','00000000-0000-4000-8000-000000000201','Trabalho técnico','Descrição',array['00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000102']::uuid[]);
select test.assert_true((select count(*)=1 from public.work_posts),'publicações: retentativa não duplica post');
select test.assert_true((select count(*)=2 from public.work_post_images),'publicações: retentativa não duplica vínculos');
select test.expect_error(format('select public.work_post_command(''publish'',%L,%L)',:'a','00000000-0000-4000-8000-000000000201'),'23514','publicações: perfil draft não publica trabalho');
select test.expect_error($q$update public.work_posts set status='published'$q$,'42501','publicações: status sem UPDATE direto');
select test.expect_error(format('insert into public.work_posts(id,business_id,title) values(gen_random_uuid(),%L,''Atalho'')',:'a'),'42501','publicações: criação somente pela RPC');
select test.expect_error($q$delete from public.work_posts$q$,'42501','publicações: DELETE direto bloqueado');
select test.expect_error(format('select public.work_post_command(''save'',%L,%L,''Teste'','''',array[%L,%L]::uuid[])',:'a','00000000-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000101'),'22023','publicações: imagens repetidas rejeitadas');
reset role;
update public.businesses set status='published' where id=:'a';
insert into public.business_members(business_id,user_id,role) values (:'a','00000000-0000-4000-8000-000000000003','admin'),(:'a','00000000-0000-4000-8000-000000000004','viewer');
set local role anon;
set local request.jwt.claim.sub='';
select test.assert_true((select count(*)=0 from public.work_posts),'publicações: anônimo não lê draft');
select test.assert_true((select count(*)=0 from public.work_post_images),'publicações: anônimo não lê fotos do draft');
select test.expect_error(format('select public.work_post_command(''publish'',%L,%L)',:'a','00000000-0000-4000-8000-000000000201'),'42501','publicações: anônimo não executa RPC');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000003';
select public.work_post_command('publish',:'a','00000000-0000-4000-8000-000000000201');
select test.assert_true((select status='published' and published_at is not null from public.work_posts),'publicações: admin publica conteúdo válido');
select published_at::text as first_publication from public.work_posts \gset
select public.work_post_command('publish',:'a','00000000-0000-4000-8000-000000000201');
select test.assert_true((select published_at=:'first_publication'::timestamptz from public.work_posts),'publicações: publicar novamente é idempotente');
reset role;
set local role anon;
select test.assert_true((select count(*)=1 from public.work_posts),'publicações: anônimo lê publicado');
select test.assert_true((select count(*)=2 from public.work_post_images),'publicações: anônimo lê somente seleção explícita');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000004';
select test.expect_error(format('select public.work_post_command(''unpublish'',%L,%L)',:'a','00000000-0000-4000-8000-000000000201'),'42501','publicações: viewer não retira trabalho');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000002';
select public.create_business('Trabalhos B','posts-b','empresa','mundo-novo-ms') as b \gset
select test.expect_error(format('select public.work_post_command(''unpublish'',%L,%L)',:'a','00000000-0000-4000-8000-000000000201'),'42501','publicações: terceiro não altera outro negócio');
select test.expect_error(format('select public.work_post_command(''save'',%L,%L,''Adotar'','''',''{}'')',:'b','00000000-0000-4000-8000-000000000201'),'42501','publicações: ID de outro negócio não pode ser adotado');
reset role;
select test.assert_true((select count(*)=1 from public.work_posts),'publicações: falha não deixa post órfão');
insert into public.portfolio_items(id,business_id,storage_path,media_state) values('00000000-0000-4000-8000-000000000103',:'b',:'b'||'/portfolio/00000000-0000-4000-8000-000000000103.webp','pending');
select test.expect_error(format('insert into public.work_post_images values(%L,%L,%L,2)','00000000-0000-4000-8000-000000000201',:'b','00000000-0000-4000-8000-000000000103'),'23503','publicações: FK composta impede mistura de negócios');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
select test.expect_error(format('select public.work_post_command(''save'',%L,%L,''Inválido'','''',array[%L]::uuid[])',:'a','00000000-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000103'),'23514','publicações: foto estrangeira ou pendente rejeitada');
select test.assert_true((select count(*)=2 from public.work_post_images),'publicações: edição inválida preserva vínculos anteriores');
select public.work_post_command('save',:'a','00000000-0000-4000-8000-000000000201','Nova ordem','Descrição',array['00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000101']::uuid[]);
select test.assert_true((select status='unpublished' from public.work_posts),'publicações: editar exige nova publicação explícita');
select test.assert_true((select sort_order=0 from public.work_post_images where portfolio_item_id='00000000-0000-4000-8000-000000000102'),'publicações: ordem de seleção preservada');
select public.work_post_command('publish',:'a','00000000-0000-4000-8000-000000000201');
select public.work_post_command('save',:'a','00000000-0000-4000-8000-000000000202','Segundo trabalho','Compartilha fotografia',array['00000000-0000-4000-8000-000000000101']::uuid[]);
select public.work_post_command('publish',:'a','00000000-0000-4000-8000-000000000202');
select public.portfolio_command('begin_delete',:'a','00000000-0000-4000-8000-000000000101');
select test.assert_true((select bool_and(status='unpublished') from public.work_posts),'publicações: begin_delete retira todas as publicações afetadas antes de remover arquivo');
reset role;
set local role anon;
select test.assert_true((select count(*)=0 from public.work_posts),'publicações: exclusão pendente oculta trabalho inteiro');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
-- Simula remoção pela API apenas no schema Storage local, sem S3.
delete from storage.objects where bucket_id='business-portfolio' and name=:'a'||'/portfolio/00000000-0000-4000-8000-000000000101.webp';
select public.portfolio_command('finish_delete',:'a','00000000-0000-4000-8000-000000000101');
select test.assert_true((select count(*)=1 from public.work_post_images),'publicações: cascade remove só referência da foto excluída');
select test.expect_error(format('select public.work_post_command(''publish'',%L,%L)',:'a','00000000-0000-4000-8000-000000000202'),'23514','publicações: perda da última foto impede republicação');
select public.work_post_command('delete',:'a','00000000-0000-4000-8000-000000000202');
select public.work_post_command('publish',:'a','00000000-0000-4000-8000-000000000201');
reset role;
update public.businesses set status='unpublished' where id=:'a';
set local role anon;
select test.assert_true((select count(*)=0 from public.work_posts),'publicações: negócio despublicado retira trabalho da leitura');
reset role;
update public.businesses set status='published' where id=:'a';
update storage.objects set metadata=null where name=:'a'||'/portfolio/00000000-0000-4000-8000-000000000102.webp';
set local role anon;
select test.assert_true((select count(*)=0 from public.work_posts),'publicações: objeto indisponível retira trabalho da leitura');
reset role;
update storage.objects set metadata='{"size":100,"mimetype":"image/webp"}' where name=:'a'||'/portfolio/00000000-0000-4000-8000-000000000102.webp';
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
select public.work_post_command('unpublish',:'a','00000000-0000-4000-8000-000000000201');
select test.assert_true((select status='unpublished' from public.work_posts),'publicações: retirada explícita funciona');
select public.work_post_command('delete',:'a','00000000-0000-4000-8000-000000000201');
select test.assert_true((select count(*)=0 from public.work_posts),'publicações: exclusão de publicação funciona');
select test.assert_true((select count(*)=0 from public.work_post_images),'publicações: exclusão remove vínculos');
select test.assert_true((select count(*)=1 from public.portfolio_items where business_id=:'a'),'publicações: excluir post preserva portfólio restante');
select test.assert_true((select count(*)=1 from storage.objects where name=:'a'||'/portfolio/00000000-0000-4000-8000-000000000102.webp'),'publicações: excluir post preserva bytes simulados');
select test.assert_true(not has_column_privilege('authenticated','public.businesses','status','UPDATE'),'publicações: proteção do status do negócio preservada');
rollback;
